+.hero-card .hint{color:var(--muted);font-size:13px}
+
+.section{padding:26px 0}
+.section-title{display:flex;align-items:end;justify-content:space-between;gap:14px;margin-bottom:14px}
+.section-title h2{margin:0;font-size:20px;letter-spacing:-.2px}
+.section-title p{margin:0;color:var(--muted);font-size:14px}
+
+.grid{display:grid;gap:14px}
+.grid.cols-3{grid-template-columns:repeat(3,minmax(0,1fr))}
+.grid.cols-2{grid-template-columns:repeat(2,minmax(0,1fr))}
