+.footer a:hover{color:var(--text);text-decoration:none}
+.footer ul{list-style:none;padding:0;margin:0;display:grid;gap:8px}
+.footer .fine{margin-top:14px;font-size:13px;color:var(--muted2)}
+
+.layout{
+  display:grid;
+  grid-template-columns:var(--sidebar) minmax(0,1fr);
+  gap:18px;
+  align-items:start;
+  padding:22px 0 30px;
+}
+
+.sidebar{
+  position:sticky;top:74px;
+  border:1px solid var(--border);
+  border-radius:var(--radius);
+  background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
+  box-shadow:0 14px 26px rgba(0,0,0,.18);
+  overflow:hidden;
+}
+
+.sidebar-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 12px;border-bottom:1px solid var(--border)}
+.sidebar-head .label{font-weight:800;font-size:13px;color:var(--muted);letter-spacing:.08em;text-transform:uppercase}
+.sidebar-nav{padding:10px}
+.sidebar-nav a{
+  display:flex;align-items:center;justify-content:space-between;gap:10px;
+  padding:9px 10px;border-radius:10px;
+  color:var(--muted);border:1px solid transparent
+}
+.sidebar-nav a:hover{color:var(--text);text-decoration:none;border-color:var(--border);background:rgba(255,255,255,.03)}
+.sidebar-nav a[aria-current="true"]{color:var(--text);border-color:rgba(34,211,238,.25);background:rgba(34,211,238,.06)}
+
+.doc{
+  border:1px solid var(--border);
+  border-radius:var(--radius);
+  background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
+  box-shadow:var(--shadow);
+  padding:18px;
+}
+.doc h1{margin:0 0 8px;font-size:30px;letter-spacing:-.5px}
+.doc .lead{margin:0 0 14px;color:var(--muted)}
+.doc h2{margin:22px 0 10px;font-size:18px;letter-spacing:-.2px}
+.doc p{margin:0 0 12px;color:var(--muted)}
+.doc ul{margin:8px 0 16px 18px;color:var(--muted)}
+.doc li{margin:6px 0}
+.doc .callout{
+  border:1px solid rgba(34,211,238,.20);
+  background:linear-gradient(135deg, rgba(34,211,238,.09), rgba(34,197,94,.06));
+  border-radius:14px;padding:12px 12px;margin:12px 0 16px;color:rgba(230,237,243,.92)
+}
+
+.collapsed .layout{grid-template-columns:72px minmax(0,1fr)}
+.collapsed .sidebar-nav a span{display:none}
+.collapsed .sidebar-head .label{display:none}
+.collapsed .sidebar-head .btn{padding:10px}
+.collapsed .sidebar{width:72px}
+
+.mobile-only{display:none}
+
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns:1fr}
+  .grid.cols-3{grid-template-columns:1fr}
+  .grid.cols-4{grid-template-columns:repeat(2,minmax(0,1fr))}
+  .launch{grid-template-columns:1fr}
+  .footer-grid{grid-template-columns:1fr 1fr}
+  .layout{grid-template-columns:1fr}
+  .sidebar{position:relative;top:auto}
+  .mobile-only{display:inline-flex}
+}
+
+@media (max-width: 560px){
+  .hero h1{font-size:36px}
+  .footer-grid{grid-template-columns:1fr}
+  .grid.cols-4{grid-template-columns:1fr}
+  .topbar-inner{align-items:flex-start}
+  .brand{min-width:auto}
+}
+
*** End Patch
